import json, glob, os, re, time, sys
from collections import Counter, defaultdict

ROOT = os.path.expanduser(r"C:\Users\eric_rash\.claude\projects")
cutoff = time.time() - 45 * 86400
files = [f for f in glob.glob(os.path.join(ROOT, "*", "*.jsonl")) if os.path.getmtime(f) >= cutoff]

NOISE = re.compile(r"^\s*(<system-reminder>|<local-command|<command-message>|Caveat:|\[Request interrupted|<user-prompt-submit-hook|<task-notification>|This session is being continued|<bash-|Base directory for this skill|<context_window|<teammate)", re.I)
CMD = re.compile(r"<command-name>/?([^<]+)</command-name>")
ARGS = re.compile(r"<command-args>(.*?)</command-args>", re.S)

def redact(s):
    s = re.sub(r"\s+", " ", s).strip()
    s = re.sub(r"[A-Z]:\\[^\s\"']+", "<path>", s)
    s = re.sub(r"\b(injur\w*|concuss\w*|ACL|hamstring|surgery|diagnos\w*|rehab\w*|dexa|body fat|weight \d+)\b", "[health]", s, flags=re.I)
    s = re.sub(r"\b[A-Z][a-z]+ [A-Z][a-z]+\b", lambda m: m.group(0) if m.group(0) in ("Kenny Boyd","Chris Ruf","Claude Code","Second Brain","Google Drive","Docker Desktop") else "<Name>", s)
    return s[:100]

sessions = 0
prompts = []  # (session, ts, text)
cmds = Counter(); skills = Counter()
seq_by_session = defaultdict(list)
for f in files:
    sid = os.path.basename(f)
    had = False
    try:
        fh = open(f, encoding="utf-8", errors="replace")
    except Exception:
        continue
    for line in fh:
        try:
            d = json.loads(line)
        except Exception:
            continue
        t = d.get("type")
        if t == "assistant":
            c = (d.get("message") or {}).get("content")
            if isinstance(c, list):
                for p in c:
                    if isinstance(p, dict) and p.get("type") == "tool_use" and p.get("name") == "Skill":
                        skills[str((p.get("input") or {}).get("skill"))] += 1
            continue
        if t != "user" or d.get("isMeta") or d.get("isSidechain") or d.get("toolUseResult") is not None:
            continue
        c = (d.get("message") or {}).get("content")
        if isinstance(c, list):
            if any(isinstance(p, dict) and p.get("type") == "tool_result" for p in c):
                continue
            c = "\n".join(p.get("text", "") for p in c if isinstance(p, dict) and p.get("type") == "text")
        if not isinstance(c, str) or not c.strip():
            continue
        m = CMD.search(c)
        if m:
            name = m.group(1).strip()
            cmds[name] += 1
            a = ARGS.search(c)
            seq_by_session[sid].append("/" + name)
            had = True
            continue
        if NOISE.match(c):
            continue
        # strip embedded reminders
        c2 = re.sub(r"<system-reminder>.*?</system-reminder>", "", c, flags=re.S).strip()
        if not c2:
            continue
        prompts.append((sid, c2))
        seq_by_session[sid].append(c2)
        had = True
    if had:
        sessions += 1

print("FILES", len(files), "SESSIONS_WITH_PROMPTS", sessions, "PROMPTS", len(prompts), "SLASH", sum(cmds.values()))
print("\n== SLASH COMMANDS ==")
for k, v in cmds.most_common(20): print(v, k)
print("\n== SKILL TOOL ==")
for k, v in skills.most_common(20): print(v, k)

def norm(s):
    s = s.lower()
    s = re.sub(r"[^a-z0-9 ']+", " ", s)
    return " ".join(s.split()[:6])

print("\n== TOP NORMALIZED OPENINGS (6 words) ==")
oc = Counter(norm(p) for _, p in prompts)
ex = {}
for _, p in prompts: ex.setdefault(norm(p), p)
for k, v in oc.most_common(30): print(v, "|", k, "|", redact(ex[k]))

KW = {
 "pull": r"\bgit pull\b|\bpull\b", "status": r"\bstatus\b", "commit": r"\bcommit\b", "push": r"\bpush\b",
 "where was i": r"where (was|were) (i|we)|where did (i|we) leave|pick up where", "handoff": r"hand ?off",
 "closeout": r"close ?out|wrap up|end of (day|session)", "stop": r"\bstop\b", "continue": r"^\s*(continue|go|proceed|keep going|yes|ok|okay|do it|go ahead)\b",
 "check": r"\bcheck\b", "verify": r"\bverif", "is X running": r"\b(is|are) .{0,30}(running|working|up|alive)\b",
 "docker": r"docker|milvus", "memsearch": r"memsearch", "backup": r"backup", "PDF": r"\bpdf\b", "email": r"e-?mail|gmail|outlook",
 "Kenny": r"kenny", "Chris": r"\bchris\b", "deck": r"\bdeck|slides?\b", "Teams": r"\bteams\b", "drive": r"google drive|\bdrive\b",
 "hook": r"\bhooks?\b", "skill": r"\bskill", "memory/remember": r"remember|memory", "fix": r"\bfix", "error": r"error|fail|broken",
 "mac/windows sync": r"\bmac\b|macbook|other machine|windows", "artifact": r"artifact", "zotero": r"zotero", "fireflies/meeting": r"fireflies|meeting",
 "plan/brainstorm": r"\bplan\b|brainstorm", "explain/eli5": r"explain|eli5|simpl", "screenshot/image": r"screenshot|\.png|image",
}
print("\n== KEYWORDS ==")
for k, rx in KW.items():
    hits = [p for _, p in prompts if re.search(rx, p, re.I)]
    exs = [redact(h) for h in hits if len(h) < 300][:2]
    print(len(hits), "|", k, "|", " || ".join(exs))

CORR = {"no,": r"^\s*no[,.!]|\bno, ", "don't": r"\bdon'?t\b|do not", "stop": r"\bstop\b", "wrong": r"\bwrong\b|incorrect", "I said": r"\bi said\b|i told you|i asked",
        "again": r"\bagain\b", "why did you": r"why did you|why are you|why would you", "instead": r"\binstead\b", "not what": r"not what i|that's not|thats not", "still": r"\bstill (not|broken|fail|doesn|isn|wrong)"}
corr = [p for _, p in prompts if any(re.search(r, p, re.I) for r in CORR.values())]
print("\n== CORRECTIONS total", len(corr))
for k, rx in CORR.items():
    hits = [p for _, p in prompts if re.search(rx, p, re.I)]
    exs = [redact(h) for h in hits if len(h) < 250][:3]
    print(len(hits), "|", k, "|", " || ".join(exs))
# theme words in correction prompts
TH = {"permissions/asking": r"ask|permission|approv|confirm", "scope creep/extra": r"just|only|don'?t (add|change|create)|unnecess", "files/paths": r"file|path|folder", "git": r"commit|push|branch|merge", "verbosity/format": r"short|concise|long|emoji|format|bullet|table", "wrong machine/os": r"mac|windows|powershell|bash", "memory": r"memory|remember", "tests/verify": r"verif|test|check", "waiting/background": r"wait|background|hang|stuck|slow"}
print("\n== CORRECTION THEMES ==")
for k, rx in TH.items():
    print(sum(1 for p in corr if re.search(rx, p, re.I)), k)

# sequences: first 3 items of each session (normalized) and bigrams of slash/short prompts
def key(x):
    return x if x.startswith("/") else norm(x)[:40]
starts = Counter(); bigr = Counter(); tri = Counter()
for sid, seq in seq_by_session.items():
    ks = [key(x) for x in seq]
    if ks: starts[ks[0]] += 1
    for i in range(len(ks) - 1): bigr[(ks[i], ks[i+1])] += 1
    for i in range(len(ks) - 2): tri[tuple(ks[i:i+3])] += 1
print("\n== SESSION OPENERS ==")
for k, v in starts.most_common(15): print(v, k)
print("\n== BIGRAMS ==")
for k, v in bigr.most_common(20):
    if v > 2: print(v, " -> ".join(k))
print("\n== TRIGRAMS ==")
for k, v in tri.most_common(10):
    if v > 2: print(v, " -> ".join(k))
lens = sorted(len(p) for _, p in prompts)
print("\nmedian prompt len", lens[len(lens)//2] if lens else 0, "short(<15 chars)", sum(1 for l in lens if l < 15))

